mapper.update:
UPDATE users
SET email = pending_email, pending_email = NULL, email_verified_at = #{at}, updated_at = #{at}
WHERE id = #{id} AND pending_email = #{email}

UPDATE users
SET email = NULL, pending_email = NULL, email_verified_at = NULL, updated_at = #{at}
WHERE id = #{id}

UPDATE users
SET username = #{username}, full_name = #{fullName}, birth_date = #{birthDate,jdbcType=DATE},
    updated_at = #{at}
WHERE id = #{id}
